+import { describe, expect, test } from "bun:test";
+import { createPlan } from "./cli";
+
+describe("createPlan", () => {
+  test("plans deterministic order, parallel layers, timings, and a tied critical path", () => {
+    const plan = createPlan([
+      { id: "ship", duration: 1, dependsOn: ["build", "test"] },
+      { id: "test", duration: 2, dependsOn: ["lint"] },
+      { id: "build", duration: 2, dependsOn: ["lint"] },
+      { id: "lint", duration: 1, dependsOn: [] },
+    ]);
+
+    expect(plan).toEqual({
+      order: ["lint", "build", "test", "ship"],
+      layers: [["lint"], ["build", "test"], ["ship"]],
+      earliest: {
+        lint: { start: 0, finish: 1 },
+        build: { start: 1, finish: 3 },
+        test: { start: 1, finish: 3 },
+        ship: { start: 3, finish: 4 },
+      },
+      totalDuration: 4,
+      criticalPath: ["lint", "build", "ship"],
+    });
+  });
+
+  test("handles no tasks and disconnected zero-duration tasks", () => {
+    expect(createPlan([])).toEqual({ order: [], layers: [], earliest: {}, totalDuration: 0, criticalPath: [] });
+    expect(createPlan([
+      { id: "z", duration: 0, dependsOn: [] },
+      { id: "a", duration: 0, dependsOn: [] },
+    ]).criticalPath).toEqual(["a"]);
+  });
+
+  test("reports a deterministic concrete cycle", () => {
+    expect(() => createPlan([
+      { id: "b", duration: 1, dependsOn: ["a"] },
+      { id: "a", duration: 1, dependsOn: ["b"] },
+    ])).toThrow("cycle detected: a -> b -> a");
+  });
+});

