display.text:
import { readFile } from "node:fs/promises";

type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

const compareIds = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

function comparePaths(a: string[], b: string[]): number {
  for (let index = 0; index < Math.min(a.length, b.length); index++) {
    const comparison = compareIds(a[index]!, b[index]!);
    if (comparison !== 0) return comparison;
  }
  return a.length - b.length;
}

function validate(value: unknown): Task[] {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    throw new Error("input must be a JSON object");
  }

  const input = value as Record<string, unknown>;
  if (!Array.isArray(input.tasks)) throw new Error("tasks must be an array");

  const tasks: Task[] = [];
  const ids = new Set<string>();
  for (let index = 0; index < input.tasks.length; index++) {
    const raw = input.tasks[index];
    const label = `tasks[${index}]`;
    if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
      throw new Error(`${label} must be an object`);
    }

    const task = raw as Record<string, unknown>;
    if (typeof task.id !== "string" || task.id.length === 0) {
      throw new Error(`${label}.id must be a non-empty string`);
    }
    if (ids.has(task.id)) throw new Error(`duplicate task id: ${task.id}`);
    if (typeof task.duration !== "number" || !Number.isFinite(task.duration) || task.duration < 0) {
      throw new Error(`${label}.duration must be a finite non-negative number`);
    }

    const rawDependencies = task.dependsOn ?? [];
    if (!Array.isArray(rawDependencies)) throw new Error(`${label}.dependsOn must be an array`);
    const dependsOn: string[] = [];
    const dependencies = new Set<string>();
    for (let dependencyIndex = 0; dependencyIndex < rawDependencies.length; dependencyIndex++) {
      const dependency = rawDependencies[dependencyIndex];
      if (typeof dependency !== "string") {
        throw new Error(`${label}.dependsOn[${dependencyIndex}] must be a string`);
      }
      if (dependencies.has(dependency)) {
        throw new Error(`${label}.dependsOn contains duplicate id: ${dependency}`);
      }
      dependencies.add(dependency);
      dependsOn.push(dependency);
    }

    ids.add(task.id);
    tasks.push({ id: task.id, duration: task.duration, dependsOn });
  }

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (dependency === task.id) throw new Error(`task ${task.id} cannot depend on itself`);
      if (!ids.has(dependency)) throw new Error(`task ${task.id} references unknown dependency: ${dependency}`);
    }
  }
  return tasks;
}

function findCycle(tasks: Task[]): string[] {
  const dependencies = new Map(tasks.map((task) => [task.id, [...task.dependsOn].sort(compareIds)]));
  const state = new Map<string, number>();
  const stack: string[] = [];

  function visit(id: string): string[] | undefined {
    state.set(id, 1);
    stack.push(id);
    for (const dependency of dependencies.get(id)!) {
      if (state.get(dependency) === 1) {
        const start = stack.indexOf(dependency);
        return [...stack.slice(start), dependency];
      }
      if (!state.has(dependency)) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    state.set(id, 2);
    return undefined;
  }

  for (const id of [...dependencies.keys()].sort(compareIds)) {
    if (!state.has(id)) {
      const cycle = visit(id);
      if (cycle) return cycle;
    }
  }
  return [];
}

export function createPlan(tasks: Task[]): Plan {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const dependents = new Map(tasks.map((task) => [task.id, [] as string[]]));
  const remaining = new Map(tasks.map((task) => [task.id, task.dependsOn.length]));
  for (const task of tasks) {
    for (const dependency of task.dependsOn) dependents.get(dependency)!.push(task.id);
  }
  for (const values of dependents.values()) values.sort(compareIds);

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort(compareIds);
  const order: string[] = [];
  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const dependent of dependents.get(id)!) {
      const count = remaining.get(dependent)! - 1;
      remaining.set(dependent, count);
      if (count === 0) {
        ready.push(dependent);
        ready.sort(compareIds);
      }
    }
  }

  if (order.length !== tasks.length) {
    throw new Error(`cycle detected: ${findCycle(tasks).join(" -> ")}`);
  }

  const layers: string[][] = [];
  const layerById = new Map<string, number>();
  const earliest: Record<string, { start: number; finish: number }> = {};
  const pathById = new Map<string, string[]>();
  for (const id of order) {
    const task = byId.get(id)!;
    const layer = task.dependsOn.length === 0
      ? 0
      : Math.max(...task.dependsOn.map((dependency) => layerById.get(dependency)!)) + 1;
    layerById.set(id, layer);
    (layers[layer] ??= []).push(id);

    let start = 0;
    let path: string[] = [];
    for (const dependency of task.dependsOn) {
      const finish = earliest[dependency]!.finish;
      const candidate = pathById.get(dependency)!;
      if (finish > start || (finish === start && (path.length === 0 || comparePaths(candidate, path) < 0))) {
        start = finish;
        path = candidate;
      }
    }
    earliest[id] = { start, finish: start + task.duration };
    pathById.set(id, [...path, id]);
  }
  for (const layer of layers) layer.sort(compareIds);

  const totalDuration = order.length === 0 ? 0 : Math.max(...order.map((id) => earliest[id]!.finish));
  let criticalPath: string[] = [];
  for (const id of order) {
    const path = pathById.get(id)!;
    if (earliest[id]!.finish === totalDuration &&
        (criticalPath.length === 0 || comparePaths(path, criticalPath) < 0)) {
      criticalPath = path;
    }
  }

  return { order, layers, earliest, totalDuration, criticalPath };
}

export async function main(args: string[]): Promise<void> {
  if (args.length !== 2 || args[0] !== "plan" || args[1]!.startsWith("-")) {
    throw new Error("usage: bun run src/cli.ts plan INPUT.json");
  }

  let source: string;
  try {
    source = await readFile(args[1]!, "utf8");
  } catch (error) {
    throw new Error(`cannot read ${args[1]}: ${error instanceof Error ? error.message : String(error)}`);
  }

  let input: unknown;
  try {
    input = JSON.parse(source);
  } catch (error) {
    throw new Error(`invalid JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
  console.log(JSON.stringify(createPlan(validate(input))));
}

if (import.meta.main) {
  main(Bun.argv.slice(2)).catch((error) => {
    console.error(`error: ${error instanceof Error ? error.message : String(error)}`);
    process.exitCode = 1;
  });
}

